/**
 * Bounded identifier validation for capture requests.
 *
 * Inputs: untrusted JSON values. Outputs: trimmed run and install identifiers or null.
 * Invariants: identifiers are short, opaque, and restricted to URL-safe characters; the
 * route never reflects them into copy.
 */

const ID_MIN = 8;
const ID_MAX = 80;
const ID_PATTERN = /^[A-Za-z0-9._:-]+$/;

/** Validates a run identifier generated by the browser. */
export function parseRunId(value: unknown): string | null {
  return parseId(value);
}

/** Validates an anonymous install identifier. */
export function parseInstallId(value: unknown): string | null {
  return parseId(value);
}

function parseId(value: unknown): string | null {
  if (typeof value !== "string") return null;
  const text = value.trim();
  if (text.length < ID_MIN || text.length > ID_MAX) return null;
  return ID_PATTERN.test(text) ? text : null;
}
